import process from "node:process";

import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";

import type { RuntimeState } from "./types.js";
import { renderPrimaryLine, renderSeparatorLine, renderUsageLine } from "./renderers.js";

// ── Constants ────────────────────────────────────────────────────────

const FOOTER_KEY = "pi-status";

// ── Extension Entry Point ────────────────────────────────────────────

export default function piStatus(pi: ExtensionAPI): void {
  let enabled = process.env.PI_STATUS !== "0";
  const runtime: RuntimeState = {
    thinkingLevel: "off",
  };

  const refresh = () => runtime.requestRender?.();

  const installFooter = (ctx: ExtensionContext) => {
    if (ctx.mode !== "tui") return;

    ctx.ui.setStatus(FOOTER_KEY, undefined);

    if (!enabled) {
      ctx.ui.setFooter(undefined);
      runtime.requestRender = undefined;
      return;
    }

    ctx.ui.setFooter((tui, _theme, footerData) => {
      runtime.requestRender = () => tui.requestRender();
      const unsubscribeBranch = footerData.onBranchChange(() => tui.requestRender());
      const clock = setInterval(() => tui.requestRender(), 60_000);

      return {
        dispose() {
          unsubscribeBranch();
          clearInterval(clock);
        },
        invalidate() {},
        render(width: number): string[] {
          if (width <= 0) return [""];
          return [
            renderPrimaryLine(width, ctx, footerData, runtime),
            renderSeparatorLine(width),
            renderUsageLine(width, ctx, footerData),
          ];
        },
      };
    });
  };

  // ── Commands ─────────────────────────────────────────────────────

  pi.registerCommand("pi-status", {
    description: "Toggle the high-contrast Pi status footer. Usage: /pi-status [on|off|toggle]",
    handler: async (args, ctx) => {
      const action = args.trim().toLowerCase();
      if (action === "on") enabled = true;
      else if (action === "off") enabled = false;
      else enabled = !enabled;

      installFooter(ctx);
      ctx.ui.notify(`High-contrast status footer ${enabled ? "enabled" : "disabled"}`, "info");
    },
  });

  // ── Event Handlers ───────────────────────────────────────────────

  pi.on("session_start", (_event, ctx) => {
    runtime.thinkingLevel = pi.getThinkingLevel();
    installFooter(ctx);
  });

  pi.on("session_tree", (_event, ctx) => {
    installFooter(ctx);
    refresh();
  });

  pi.on("session_shutdown", (_event, ctx) => {
    if (ctx.mode === "tui") ctx.ui.setFooter(undefined);
    ctx.ui.setStatus(FOOTER_KEY, undefined);
    runtime.requestRender = undefined;
  });

  pi.on("model_select", () => refresh());
  pi.on("agent_end", () => refresh());
  pi.on("turn_end", () => refresh());

  pi.on("thinking_level_select", (event) => {
    runtime.thinkingLevel = event.level;
    refresh();
  });
}

import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";

// ── Thinking ─────────────────────────────────────────────────────────

export type ThinkingLevel = ReturnType<ExtensionAPI["getThinkingLevel"]>;

// ── Runtime ──────────────────────────────────────────────────────────

export interface RuntimeState {
  thinkingLevel: ThinkingLevel;
  requestRender?: () => void;
}

// ── Tokens / Cost ────────────────────────────────────────────────────

export interface TokenTotals {
  input: number;
  output: number;
  cost: number;
}

// ── Chip UI ──────────────────────────────────────────────────────────

export interface Chip {
  label: string;
  value: string;
  accent: string;
  priority: 1 | 2 | 3;
  labelFg?: string;
  valueFg?: string;
  valueBg?: string;
  boldValue?: boolean;
}

// ── Git ──────────────────────────────────────────────────────────────

export interface GitSnapshot {
  branch?: string;
  worktreeName?: string;
  statusParts?: GitStatusPart[];
  dirty: boolean;
  expiresAt: number;
}

export interface GitStatusPart {
  symbol: string;
  count: number;
  color: string;
}

export interface GitStatusCounts {
  conflicted: number;
  modified: number;
  untracked: number;
  staged: number;
  renamed: number;
  deleted: number;
  ahead: number;
  behind: number;
}

import { execFileSync } from "node:child_process";
import { basename, dirname } from "node:path";

import type { GitSnapshot, GitStatusCounts, GitStatusPart } from "./types.js";
import { COLOR } from "./theme.js";

// ── Constants ────────────────────────────────────────────────────────

const GIT_CACHE_TTL_MS = 2_000;
const GIT_COMMAND_TIMEOUT_MS = 350;

// ── Cache ────────────────────────────────────────────────────────────

const gitCache = new Map<string, GitSnapshot>();

// ── Public API ───────────────────────────────────────────────────────

export function getGitSnapshot(cwd: string, fallbackBranch?: string): GitSnapshot {
  const now = Date.now();
  const cached = gitCache.get(cwd);
  if (cached && cached.expiresAt > now) {
    return fallbackBranch && cached.branch !== fallbackBranch ? { ...cached, branch: fallbackBranch } : cached;
  }

  try {
    const worktreeRoot = execGit(cwd, ["rev-parse", "--show-toplevel"]);
    const worktreeName = getLinkedWorktreeName(cwd, worktreeRoot);
    const statusOutput = execGit(cwd, ["status", "--porcelain=v1", "--branch"]);
    const parsed = parseGitStatus(statusOutput);
    const snapshot: GitSnapshot = {
      branch: fallbackBranch ?? parsed.branch,
      worktreeName,
      statusParts: formatGitStatus(parsed.counts),
      dirty: isDirty(parsed.counts),
      expiresAt: now + GIT_CACHE_TTL_MS,
    };
    gitCache.set(cwd, snapshot);
    return snapshot;
  } catch {
    const snapshot: GitSnapshot = {
      branch: fallbackBranch,
      dirty: false,
      expiresAt: now + GIT_CACHE_TTL_MS,
    };
    gitCache.set(cwd, snapshot);
    return snapshot;
  }
}

// ── Git Commands ─────────────────────────────────────────────────────

function execGit(cwd: string, args: string[]): string {
  return execFileSync("git", ["-C", cwd, ...args], {
    encoding: "utf8",
    maxBuffer: 1024 * 1024,
    stdio: ["ignore", "pipe", "ignore"],
    timeout: GIT_COMMAND_TIMEOUT_MS,
  }).trim();
}

function getLinkedWorktreeName(cwd: string, worktreeRoot: string): string | undefined {
  try {
    const gitDir = execGit(cwd, ["rev-parse", "--absolute-git-dir"]);
    if (basename(dirname(gitDir)) !== "worktrees") return undefined;
    return basename(worktreeRoot) || undefined;
  } catch {
    return undefined;
  }
}

// ── Status Parsing ───────────────────────────────────────────────────

function parseGitStatus(output: string): { branch?: string; counts: GitStatusCounts } {
  const counts: GitStatusCounts = {
    conflicted: 0,
    modified: 0,
    untracked: 0,
    staged: 0,
    renamed: 0,
    deleted: 0,
    ahead: 0,
    behind: 0,
  };
  let branch: string | undefined;

  for (const line of output.split(/\r?\n/)) {
    if (!line) continue;

    if (line.startsWith("## ")) {
      branch = parseStatusBranch(line.slice(3));
      counts.ahead += Number(line.match(/ahead (\d+)/)?.[1] ?? 0);
      counts.behind += Number(line.match(/behind (\d+)/)?.[1] ?? 0);
      continue;
    }

    const x = line[0];
    const y = line[1];
    const xy = `${x}${y}`;

    if (xy === "??") {
      counts.untracked += 1;
      continue;
    }
    if (xy === "!!") continue;
    if (["DD", "AU", "UD", "UA", "DU", "AA", "UU"].includes(xy)) {
      counts.conflicted += 1;
      continue;
    }

    if (x === "R" || x === "C") counts.renamed += 1;
    else if (x === "D") counts.deleted += 1;
    else if (x !== " ") counts.staged += 1;

    if (y === "D") counts.deleted += 1;
    else if (y === "M" || y === "T") counts.modified += 1;
  }

  return { branch, counts };
}

function parseStatusBranch(header: string): string | undefined {
  const value = header.replace(/\s+\[[^\]]+\]$/, "").split("...")[0];
  if (!value || value.startsWith("HEAD ")) return undefined;
  return value;
}

// ── Status Formatting ────────────────────────────────────────────────

function formatGitStatus(counts: GitStatusCounts): GitStatusPart[] | undefined {
  const parts = [
    formatGitStatusPart("=", counts.conflicted, COLOR.contextRed),
    formatGitStatusPart("⇡", counts.ahead, COLOR.gitStaged),
    formatGitStatusPart("⇣", counts.behind, COLOR.gitDeleted),
    formatGitStatusPart("✘", counts.untracked, COLOR.gitUntracked),
    formatGitStatusPart("~", counts.modified, COLOR.gitModified),
    formatGitStatusPart("+", counts.staged, COLOR.gitStaged),
    formatGitStatusPart("»", counts.renamed, COLOR.gitRenamed),
    formatGitStatusPart("-", counts.deleted, COLOR.gitDeleted),
  ].filter((part): part is GitStatusPart => part !== undefined);

  return parts.length > 0 ? parts : undefined;
}

function formatGitStatusPart(symbol: string, count: number, color: string): GitStatusPart | undefined {
  return count > 0 ? { symbol, count, color } : undefined;
}

function isDirty(counts: GitStatusCounts): boolean {
  return counts.conflicted + counts.modified + counts.untracked + counts.staged + counts.renamed + counts.deleted > 0;
}

import type { ExtensionContext, ReadonlyFooterDataProvider } from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

import type { Chip, GitStatusPart, RuntimeState } from "./types.js";
import { ansi } from "./ansi.js";
import { chip, renderChip, renderChips, renderSegmentedChip } from "./chips.js";
import {
  codexValueSegments,
  contextSnapshot,
  formatCodexValue,
  formatCost,
  formatCount,
  formatThinking,
  formatWorkingPath,
  getTokenTotals,
  modelName,
  shorten,
  smartPathTruncate,
} from "./format.js";
import { getGitSnapshot } from "./git.js";
import { COLOR, codexAccent, thinkingColor } from "./theme.js";

// ── Constants ────────────────────────────────────────────────────────

const CODEX_USAGE_STATUS_KEY = "codex-usage";

// ── Line Renderers ───────────────────────────────────────────────────

export function renderPrimaryLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
  runtime: RuntimeState,
): string {
  const context = contextSnapshot(ctx);
  const right: Chip[] = [
    chip("MODEL", modelName(ctx), COLOR.model, 1, { valueBg: COLOR.panelLift, boldValue: true }),
    chip("THINK", formatThinking(runtime.thinkingLevel), thinkingColor(runtime.thinkingLevel), 2, {
      valueBg: COLOR.panelLift,
    }),
    chip("CTX", context.label, context.color, 1, {
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  ];

  return fitLeftRight(width, right, (available) => renderPathCluster(available, ctx, footerData));
}

export function renderUsageLine(
  width: number,
  ctx: ExtensionContext,
  footerData: ReadonlyFooterDataProvider,
): string {
  const totals = getTokenTotals(ctx);
  const right: Chip[] = [
    chip("↑", formatCount(totals.input), COLOR.token, 1),
    chip("↓", formatCount(totals.output), COLOR.token, 1),
    chip("$", formatCost(totals.cost), COLOR.cost, 2, { boldValue: true }),
  ];

  return fitLeftRight(width, right, (available) => renderCodexStatus(available, footerData));
}

export function renderSeparatorLine(width: number): string {
  return ansi("─".repeat(Math.max(0, width)), { fg: COLOR.separator });
}

// ── Layout ───────────────────────────────────────────────────────────

function fitLeftRight(width: number, rightChips: Chip[], renderLeft: (available: number) => string): string {
  for (let priority = 3; priority >= 1; priority -= 1) {
    const right = renderChips(rightChips.filter((item) => item.priority <= priority));
    const rightWidth = visibleWidth(right);
    const gap = rightWidth > 0 ? 1 : 0;
    const availableLeft = Math.max(0, width - rightWidth - gap);
    const left = renderLeft(availableLeft);
    const leftWidth = visibleWidth(left);

    if (leftWidth + rightWidth + gap <= width) {
      const padding = " ".repeat(Math.max(gap, width - leftWidth - rightWidth));
      return truncateToWidth(`${left}${padding}${right}`, width, "");
    }
  }

  return truncateToWidth(renderLeft(width), width, "");
}

// ── Path Cluster ─────────────────────────────────────────────────────

function renderPathCluster(maxWidth: number, ctx: ExtensionContext, footerData: ReadonlyFooterDataProvider): string {
  if (maxWidth <= 0) return "";

  const footerBranch = footerData.getGitBranch() ?? undefined;
  const git = getGitSnapshot(ctx.cwd, footerBranch);
  const branch = git.branch ?? footerBranch;
  const fullPath = formatWorkingPath(ctx.cwd);

  for (const attempt of [
    { worktreeWidth: 24, branchWidth: 28, includeStatus: true },
    { worktreeWidth: 18, branchWidth: 18, includeStatus: true },
    { worktreeWidth: 12, branchWidth: 12, includeStatus: true },
    { worktreeWidth: 18, branchWidth: 18, includeStatus: false },
    { worktreeWidth: 18, branchWidth: 0, includeStatus: false },
    { worktreeWidth: 0, branchWidth: 18, includeStatus: true },
    { worktreeWidth: 0, branchWidth: 18, includeStatus: false },
    { worktreeWidth: 0, branchWidth: 0, includeStatus: false },
  ]) {
    const worktreeChip =
      attempt.worktreeWidth > 0 && git.worktreeName ? renderWorktreeChip(git.worktreeName, attempt.worktreeWidth) : "";
    const branchChip =
      attempt.branchWidth > 0 && branch ? renderBranchChip(branch, attempt.branchWidth, attempt.includeStatus ? git.statusParts : undefined) : "";
    const fixed = [worktreeChip, branchChip].filter(Boolean).join(" ");
    const fixedWidth = visibleWidth(fixed);
    const gap = fixedWidth > 0 ? 1 : 0;
    const pathMaxWidth = Math.max(0, maxWidth - fixedWidth - gap);
    const pathChip = renderFittedPathChip(fullPath, pathMaxWidth);
    const cluster = [pathChip, fixed].filter(Boolean).join(" ");

    if (visibleWidth(cluster) <= maxWidth) return cluster;
  }

  return truncateToWidth(renderFittedPathChip(fullPath, maxWidth), maxWidth, "");
}

// ── Path Chips ───────────────────────────────────────────────────────

function renderPathChip(value: string): string {
  return renderChip(
    chip("", value, COLOR.path, 1, {
      labelFg: COLOR.black,
      valueBg: COLOR.panelLift,
      boldValue: true,
    }),
  );
}

function renderFittedPathChip(path: string, maxWidth: number): string {
  if (maxWidth <= 0) return "";

  const fullPathChip = renderPathChip(path);
  if (visibleWidth(fullPathChip) <= maxWidth) return fullPathChip;

  const emptyPathChipWidth = visibleWidth(renderPathChip(""));
  const pathWidth = Math.max(3, maxWidth - emptyPathChipWidth);
  return truncateToWidth(renderPathChip(smartPathTruncate(path, pathWidth)), maxWidth, "");
}

// ── Git Chips ────────────────────────────────────────────────────────

function renderBranchChip(branch: string, maxWidth: number, statusParts?: GitStatusPart[]): string {
  const branchText = shorten(branch, maxWidth);
  const segments = [
    { text: branchText, fg: COLOR.git, bold: true },
    ...(statusParts ?? []).map((part) => ({ text: `${part.symbol}${part.count}`, fg: part.color, bold: true })),
  ];

  return renderSegmentedChip("", segments, COLOR.git, { labelFg: COLOR.black, valueBg: COLOR.panelLift });
}

function renderWorktreeChip(worktreeName: string, maxWidth: number): string {
  return renderChip(chip("󰙅", shorten(worktreeName, maxWidth), COLOR.git, 2, { labelFg: COLOR.black }));
}

// ── Codex Chip ───────────────────────────────────────────────────────

function renderCodexStatus(maxWidth: number, footerData: ReadonlyFooterDataProvider): string {
  if (maxWidth <= 0) return "";

  const raw = footerData.getExtensionStatuses().get(CODEX_USAGE_STATUS_KEY);
  const value = formatCodexValue(raw);
  const accent = codexAccent(raw);
  const segments = codexValueSegments(value);
  const full = renderSegmentedChip("CODEX", segments, accent, {
    labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
    valueBg: COLOR.panelLift,
  });
  if (visibleWidth(full) <= maxWidth) return full;

  const emptyWidth = visibleWidth(
    renderChip(
      chip("CODEX", "", accent, 1, {
        labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
        valueBg: COLOR.panelLift,
      }),
    ),
  );
  const valueWidth = Math.max(1, maxWidth - emptyWidth);
  return truncateToWidth(
    renderChip(
      chip("CODEX", truncateToWidth(value, valueWidth, "…"), accent, 1, {
        labelFg: accent === COLOR.contextWarn || accent === COLOR.codex ? COLOR.black : COLOR.ink,
        valueBg: COLOR.panelLift,
        boldValue: Boolean(raw),
      }),
    ),
    maxWidth,
    "",
  );
}

import { homedir } from "node:os";

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { truncateToWidth, visibleWidth } from "@earendil-works/pi-tui";

import type { ThinkingLevel, TokenTotals } from "./types.js";
import { stripAnsi } from "./ansi.js";
import { COLOR, codexPercentColor, contextColor } from "./theme.js";

// ── Context ──────────────────────────────────────────────────────────

export function contextSnapshot(ctx: ExtensionContext): { label: string; color: string } {
  const usage = ctx.getContextUsage();
  const percent = typeof usage?.percent === "number" ? usage.percent : undefined;
  if (percent === undefined) return { label: "?", color: COLOR.contextTransparent };

  const clamped = Math.max(0, Math.min(100, percent));
  return { label: `${clamped.toFixed(0)}%`, color: contextColor(clamped) };
}

// ── Model ────────────────────────────────────────────────────────────

export function modelName(ctx: ExtensionContext): string {
  const model = ctx.model as { id?: string; name?: string } | undefined;
  return shortenModel(model?.id ?? model?.name ?? "no model");
}

export function shortenModel(model: string): string {
  return shorten(
    model
      .replace(/^claude-/, "")
      .replace(/^gpt-/, "gpt ")
      .replace(/-20\d{6}$/, "")
      .replace(/-latest$/, "")
      .replace(/-(instruct|preview|thinking)$/i, ""),
    28,
  );
}

// ── Thinking ─────────────────────────────────────────────────────────

export function formatThinking(level: ThinkingLevel): string {
  if (level === "xhigh") return "x-high";
  return level;
}

// ── Tokens / Cost ────────────────────────────────────────────────────

export function getTokenTotals(ctx: ExtensionContext): TokenTotals {
  const totals: TokenTotals = { input: 0, output: 0, cost: 0 };

  for (const entry of ctx.sessionManager.getBranch()) {
    if (entry.type !== "message") continue;
    const message = entry.message as {
      role?: string;
      usage?: { input?: number; output?: number; cost?: { total?: number } };
    };
    if (message.role !== "assistant") continue;

    totals.input += message.usage?.input ?? 0;
    totals.output += message.usage?.output ?? 0;
    totals.cost += message.usage?.cost?.total ?? 0;
  }

  return totals;
}

export function formatCount(value: number): string {
  if (value < 1000) return `${value}`;
  if (value < 1_000_000) return `${(value / 1000).toFixed(value < 10_000 ? 1 : 0)}k`;
  return `${(value / 1_000_000).toFixed(1)}m`;
}

export function formatCost(value: number): string {
  return value >= 1 ? value.toFixed(2) : value.toFixed(3);
}

// ── Codex Status ─────────────────────────────────────────────────────

export function formatCodexValue(raw: string | undefined): string {
  if (!raw) return "usage —";

  const value = simplifyStatusText(raw)
    .replace(/^📊\s*/u, "")
    .replace(/^codex\b\s*/iu, "")
    .replace(/\s+(5h|wk)\b/giu, " $1")
    .replace(/\s+/g, " ")
    .trim();

  return value || "usage —";
}

export function codexValueSegments(value: string): Array<{ text: string; fg: string; bold?: boolean }> {
  return value.split(/\s+/).map((token) => {
    const percent = Number(token.match(/^(\d{1,3})%$/)?.[1]);
    if (Number.isFinite(percent)) {
      return { text: token, fg: codexPercentColor(percent), bold: true };
    }
    return { text: token, fg: /^(5h|wk)$/iu.test(token) ? COLOR.dim : COLOR.soft };
  });
}

// ── Paths ────────────────────────────────────────────────────────────

export function formatWorkingPath(cwd: string): string {
  const home = homedir();
  if (cwd === home) return "~";
  if (cwd.startsWith(`${home}/`)) return `~/${cwd.slice(home.length + 1)}`;
  return cwd;
}

export function smartPathTruncate(path: string, maxWidth: number): string {
  if (visibleWidth(path) <= maxWidth) return path;
  const parts = path.split("/").filter(Boolean);
  if (parts.length >= 2 && maxWidth >= 12) {
    const tail = parts.slice(-2).join("/");
    return truncateToWidth(`…/${tail}`, maxWidth, "…");
  }
  return truncateToWidth(path, maxWidth, "…");
}

// ── Shared Utilities ─────────────────────────────────────────────────

export function shorten(value: string, maxWidth: number): string {
  return truncateToWidth(value, maxWidth, "…");
}

function simplifyStatusText(value: string): string {
  return stripAnsi(value)
    .trim()
    .replace(/,\s*/g, " ")
    .replace(/\s+\([^)]*\)\s*$/, "")
    .replace(/\s+/g, " ");
}

import type { Chip } from "./types.js";
import { ansi, readableTextOn } from "./ansi.js";
import { COLOR } from "./theme.js";

// ── Chip Factory ─────────────────────────────────────────────────────

export function chip(
  label: string,
  value: string,
  accent: string,
  priority: 1 | 2 | 3,
  options: Partial<Pick<Chip, "labelFg" | "valueFg" | "valueBg" | "boldValue">> = {},
): Chip {
  return {
    label,
    value,
    accent,
    priority,
    labelFg: options.labelFg,
    valueFg: options.valueFg,
    valueBg: options.valueBg,
    boldValue: options.boldValue,
  };
}

// ── Chip Renderers ───────────────────────────────────────────────────

export function renderChips(chips: Chip[]): string {
  return chips.map(renderChip).join(" ");
}

export function renderChip(item: Chip): string {
  const labelFg = item.labelFg ?? readableTextOn(item.accent);
  const valueFg = item.valueFg ?? item.accent;
  const valueBg = item.valueBg ?? COLOR.panel;

  return [
    ansi("", { fg: item.accent }),
    ansi(` ${item.label} `, { fg: labelFg, bg: item.accent, bold: true }),
    ansi("", { fg: item.accent, bg: valueBg }),
    ansi(` ${item.value} `, { fg: valueFg, bg: valueBg, bold: item.boldValue }),
    ansi("", { fg: valueBg }),
  ].join("");
}

export function renderSegmentedChip(
  label: string,
  segments: Array<{ text: string; fg: string; bold?: boolean }>,
  accent: string,
  options: { labelFg?: string; valueBg?: string } = {},
): string {
  const labelFg = options.labelFg ?? readableTextOn(accent);
  const valueBg = options.valueBg ?? COLOR.panel;
  const value = segments
    .map((segment, index) => {
      const prefix = index === 0 ? "" : ansi(" ", { bg: valueBg });
      return `${prefix}${ansi(segment.text, { fg: segment.fg, bg: valueBg, bold: segment.bold })}`;
    })
    .join("");

  return [
    ansi("", { fg: accent }),
    ansi(` ${label} `, { fg: labelFg, bg: accent, bold: true }),
    ansi("", { fg: accent, bg: valueBg }),
    ansi(" ", { bg: valueBg }),
    value,
    ansi(" ", { bg: valueBg }),
    ansi("", { fg: valueBg }),
  ].join("");
}

import { COLOR } from "./theme.js";

// ── ANSI Escape Helpers ──────────────────────────────────────────────

/** Apply SGR (Select Graphic Rendition) codes around `text`. */
export function ansi(
  text: string,
  options: { fg?: string; bg?: string; bold?: boolean },
): string {
  const codes = [
    options.bold ? "1" : undefined,
    options.fg ? rgbCode("38", options.fg) : undefined,
    options.bg ? rgbCode("48", options.bg) : undefined,
  ].filter((code): code is string => code !== undefined);

  if (codes.length === 0) return text;
  return `\u001b[${codes.join(";")}m${text}\u001b[0m`;
}

/** Strip all ANSI escape sequences from a string. */
export function stripAnsi(value: string): string {
  return value.replace(/\u001b(?:[@-Z\\-_]|\[[0-?]*[ -/]*[@-~])/g, "");
}

/** Pick a readable text color (black or white) for a given background. */
export function readableTextOn(hex: string): string {
  const { red, green, blue } = hexToRgb(hex);
  const luminance = (0.299 * red + 0.587 * green + 0.114 * blue) / 255;
  return luminance > 0.55 ? COLOR.black : COLOR.ink;
}

// ── Internal ─────────────────────────────────────────────────────────

function rgbCode(prefix: "38" | "48", hex: string): string {
  const { red, green, blue } = hexToRgb(hex);
  return `${prefix};2;${red};${green};${blue}`;
}

function hexToRgb(hex: string): { red: number; green: number; blue: number } {
  const normalized = hex.replace(/^#/, "");
  return {
    red: Number.parseInt(normalized.slice(0, 2), 16),
    green: Number.parseInt(normalized.slice(2, 4), 16),
    blue: Number.parseInt(normalized.slice(4, 6), 16),
  };
}

